using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Numerics;

// Exact BigInteger port. No maximum denominator is imposed.
public sealed class NativeEgyptian
{
    struct Rat { public BigInteger A,B; public Rat(BigInteger a,BigInteger b) { BigInteger g=BigInteger.GreatestCommonDivisor(a,b); A=a/g;B=b/g; } }
    struct HKey : IEquatable<HKey> { public BigInteger D;public int T;public HKey(BigInteger d,int t){D=d;T=t;}public bool Equals(HKey k){return D==k.D&&T==k.T;}public override bool Equals(object x){return x is HKey&&Equals((HKey)x);}public override int GetHashCode(){return D.GetHashCode()*37+T;} }
    struct SKey : IEquatable<SKey> { public BigInteger D,A,B;public int T;public SKey(BigInteger d,int t,BigInteger a,BigInteger b){D=d;T=t;A=a;B=b;}public bool Equals(SKey k){return D==k.D&&T==k.T&&A==k.A&&B==k.B;}public override bool Equals(object x){return x is SKey&&Equals((SKey)x);}public override int GetHashCode(){unchecked{return (((D.GetHashCode()*37+T)*37+A.GetHashCode())*37+B.GetHashCode());}} }
    readonly Stopwatch watch=new Stopwatch();readonly double limit;readonly bool primePrune;readonly int memoLimit;
    readonly Dictionary<HKey,Rat> harmonics=new Dictionary<HKey,Rat>();
    readonly Dictionary<BigInteger,int[]> factors=new Dictionary<BigInteger,int[]>();
    readonly HashSet<SKey> failed=new HashSet<SKey>();
    readonly List<BigInteger> path=new List<BigInteger>();
    long nodes,hprunes,pprunes,mhits,twoPrunes,twoCandidates;double nextReport=15;
    NativeEgyptian(double seconds,bool primes,int memo){limit=seconds;primePrune=primes;memoLimit=memo;watch.Start();}
    static Rat AddUnit(Rat r,BigInteger x){return new Rat(r.A*x+r.B,r.B*x);}
    static void SubtractUnit(BigInteger a,BigInteger b,BigInteger x,out BigInteger aa,out BigInteger bb){BigInteger h=BigInteger.GreatestCommonDivisor(b,x),c=a*(x/h)-b/h,j=h==1?BigInteger.One:BigInteger.GreatestCommonDivisor(c,h);aa=c/j;bb=(b/h)*(x/j);}
    Rat Harmonic(BigInteger d,int t){HKey k=new HKey(d,t);Rat h;if(harmonics.TryGetValue(k,out h))return h;h=new Rat(0,1);for(int j=0;j<t;j++)h=AddUnit(h,d+j);if(harmonics.Count<250000)harmonics[k]=h;return h;}
    bool Enough(BigInteger d,int t,BigInteger a,BigInteger b){Rat h=Harmonic(d,t);return h.A*b>=a*h.B;}
    BigInteger Upper(BigInteger d,int t,BigInteger a,BigInteger b){BigInteger hi=t*b/a,lo=d-1;while(lo<hi){BigInteger mid=(lo+hi+1)/2;if(Enough(mid,t,a,b))lo=mid;else hi=mid-1;}return lo;}
    int[] Factor(BigInteger n){int[] ans;if(factors.TryGetValue(n,out ans))return ans;BigInteger r=n;List<int> p=new List<int>();int d=2;while((BigInteger)d*d<=r&&d<=10000){if(r%d==0){p.Add(d);while(r%d==0)r/=d;}d=d==2?3:d+2;}if(r>1&&(BigInteger)d*d>r)p.Add((int)r);ans=p.ToArray();if(factors.Count<100000)factors[n]=ans;return ans;}
    int[] Merge(int[] p,int[] q){HashSet<int> s=new HashSet<int>(p);foreach(int x in q)s.Add(x);int[] a=new int[s.Count];s.CopyTo(a);Array.Sort(a);return a;}
    static BigInteger Inv(BigInteger a,int p){BigInteger oldr=p,r=a%p,oldt=0,t=1;while(r!=0){BigInteger q=oldr/r,tmp=oldr-q*r;oldr=r;r=tmp;tmp=oldt-q*t;oldt=t;t=tmp;}if(oldr!=1)throw new Exception("noninvertible residue");oldt%=p;if(oldt<0)oldt+=p;return oldt;}
    Rat Forced(BigInteger d,int t,BigInteger q1,BigInteger q2,bool two){Rat h=new Rat(0,1);h=AddUnit(h,q1);if(two)h=AddUnit(h,q2);int needed=t-(two?2:1);BigInteger x=d;while(needed>0){if(x!=q1&&(!two||x!=q2)){h=AddUnit(h,x);needed--;}x++;}return h;}
    bool PrimeObstruction(BigInteger d,int t,BigInteger a,BigInteger b,int[] primes){if(!primePrune||b==1||t<=1)return false;foreach(int p in primes){BigInteger v=b,pe=1;while(v%p==0){pe*=p;v/=p;}if(pe==1)continue;BigInteger q1=((d+pe-1)/pe)*pe,q2=q1+pe;if(q2<d+t)continue;Rat h2=q1<d+t-1?AddUnit(Harmonic(d,t-1),q2):AddUnit(AddUnit(Harmonic(d,t-2),q1),q2);if(h2.A*b>=a*h2.B)continue;BigInteger unit=(v*Inv(a,p))%p,mod=pe*p,res=pe*unit;BigInteger q=res;if(q<d)q+=((d-q+mod-1)/mod)*mod;if(q<d+t)continue;Rat h1=AddUnit(Harmonic(d,t-1),q);if(h1.A*b<a*h1.B)return true;}return false;}
    static BigInteger Sqrt(BigInteger n){if(n<0)throw new ArgumentOutOfRangeException();if(n<2)return n;byte[] bytes=n.ToByteArray();int last=bytes.Length-1;while(last>0&&bytes[last]==0)last--;int top=bytes[last],bits=last*8;while(top>0){bits++;top>>=1;}BigInteger x=BigInteger.One<<((bits+1)/2);while(true){BigInteger y=(x+n/x)/2;if(y>=x)return x;x=y;}}
    List<BigInteger> Two(BigInteger d,BigInteger a,BigInteger b){BigInteger lo=BigInteger.Max(d,b/a+1),hi=(2*b-1)/a;if(hi<lo||lo*lo-a*lo+b<0){twoPrunes++;return null;}BigInteger delta=a*a-4*b;if(delta>0){BigInteger s=Sqrt(delta);if(s*s<delta)s++;hi=BigInteger.Min(hi,(a-s)/2);}if(hi<lo){twoPrunes++;return null;}for(BigInteger x=lo;x<=hi;x++){twoCandidates++;if((twoCandidates&1023)==0)Tick();BigInteger rem,y=BigInteger.DivRem(b*x,a*x-b,out rem);if(rem==0&&y>x)return new List<BigInteger>{x,y};}return null;}
    void Tick(){double elapsed=watch.Elapsed.TotalSeconds;if(elapsed>=limit)throw new TimeoutException();if(elapsed>=nextReport){Console.WriteLine("{\"event\":\"progress\",\"elapsed_seconds\":"+elapsed.ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+",\"nodes\":"+nodes+",\"prime_prunes\":"+pprunes+",\"quadratic_two_prunes\":"+twoPrunes+",\"current_prefix\":["+string.Join(",",path)+"]}");nextReport=elapsed+15;}}
    List<BigInteger> Dfs(BigInteger d,int t,BigInteger a,BigInteger b,int[] primes){nodes++;if((nodes&1023)==0)Tick();if(t==0)return a==0?new List<BigInteger>():null;if(a<=0)return null;if(t==1){if(b%a==0&&b/a>=d)return new List<BigInteger>{b/a};return null;}if(t==2)return Two(d,a,b);if(!Enough(d,t,a,b)){hprunes++;return null;}SKey key=new SKey(d,t,a,b);if(failed.Contains(key)){mhits++;return null;}if(PrimeObstruction(d,t,a,b,primes)){pprunes++;return null;}BigInteger lo=BigInteger.Max(d,b/a+1),hi=Upper(lo,t,a,b);for(BigInteger x=lo;x<=hi;x++){BigInteger na,nb;SubtractUnit(a,b,x,out na,out nb);if(na<=0)continue;int[] nextprimes=t>3?Merge(primes,Factor(x)):primes;path.Add(x);List<BigInteger> tail=Dfs(x+1,t-1,na,nb,nextprimes);path.RemoveAt(path.Count-1);if(tail!=null){tail.Insert(0,x);return tail;}}if(failed.Count<memoLimit)failed.Add(key);return null;}
    public static string VerifyReduction(){Random r=new Random(910115);for(int i=0;i<10000;i++){Rat f=new Rat((BigInteger)r.Next(1,1000000000)*r.Next(1,1000000000),(BigInteger)r.Next(1,1000000000)*r.Next(1,1000000000));BigInteger x=r.Next(2,1000000),aa,bb;SubtractUnit(f.A,f.B,x,out aa,out bb);Rat old=new Rat(f.A*x-f.B,f.B*x);if(aa!=old.A||bb!=old.B)throw new Exception("reduction oracle");}return "10000 exact fraction-subtraction reduction oracles passed";}
    public static string Verify(){Random r=new Random(823100);for(int i=0;i<1000;i++){BigInteger n=i<500?i:(BigInteger)r.Next(1,1000000000)*r.Next(1,1000000000);BigInteger q=Sqrt(n);if(q*q>n||(q+1)*(q+1)<=n)throw new Exception("sqrt oracle");}for(int i=0;i<500;i++){Rat f=new Rat(r.Next(1,500),r.Next(2,1000));BigInteger d=r.Next(2,50),lo=BigInteger.Max(d,f.B/f.A+1),hi=(2*f.B-1)/f.A;bool oracle=false;for(BigInteger x=lo;x<=hi;x++){BigInteger rem,y=BigInteger.DivRem(f.B*x,f.A*x-f.B,out rem);if(rem==0&&y>x){oracle=true;break;}}NativeEgyptian s=new NativeEgyptian(60,false,0);List<BigInteger> got=s.Two(d,f.A,f.B);if((got!=null)!=oracle)throw new Exception("two oracle");}for(int i=0;i<4000;i++){int t=r.Next(2,11);HashSet<int> ds=new HashSet<int>();while(ds.Count<t)ds.Add(r.Next(2,160));int[] aa=new int[t];ds.CopyTo(aa);Array.Sort(aa);Rat f=new Rat(0,1);foreach(int x in aa)f=AddUnit(f,x);NativeEgyptian s=new NativeEgyptian(60,true,0);if(s.PrimeObstruction(aa[0],t,f.A,f.B,s.Factor(f.B)))throw new Exception("prime rejects genuine witness");}for(int i=0;i<100;i++){Rat f=new Rat(r.Next(1,20),r.Next(2,21));int d=r.Next(2,13),t=r.Next(2,4);NativeEgyptian s1=new NativeEgyptian(60,false,2000),s2=new NativeEgyptian(60,true,2000);List<BigInteger> w1=s1.Dfs(d,t,f.A,f.B,s1.Factor(f.B)),w2=s2.Dfs(d,t,f.A,f.B,s2.Factor(f.B));if((w1!=null)!=(w2!=null))throw new Exception("on off disagreement");}return "1000 integer square roots, 500 exact terminal oracles, 4000 genuine prime-prune witnesses, 100 full ON/OFF residual searches passed";}
    public static string Run(int minimum,int terms,double seconds,int[] prefix,bool usePrimes,int memo){NativeEgyptian s=new NativeEgyptian(seconds,usePrimes,memo);BigInteger a=1,b=1;BigInteger d=minimum;List<BigInteger> first=new List<BigInteger>();foreach(int x in prefix){if(x<d)throw new ArgumentException("prefix must increase and be >= minimum");BigInteger na=a*x-b,nb=b*x;BigInteger g=BigInteger.GreatestCommonDivisor(na,nb);a=na/g;b=nb/g;d=x+1;first.Add(x);s.path.Add(x);}string status;List<BigInteger> solution=null;try{solution=s.Dfs(d,terms-prefix.Length,a,b,s.Factor(b));status=solution==null?"exhausted":"found";}catch(TimeoutException){status="timeout";}if(solution!=null)solution.InsertRange(0,first);string witness=solution==null?"null":"["+string.Join(",",solution)+"]";return "{\"event\":\"result\",\"status\":\""+status+"\",\"minimum\":"+minimum+",\"terms\":"+terms+",\"prefix\":["+string.Join(",",prefix)+"],\"max_denominator\":null,\"denominators\":"+witness+",\"elapsed_seconds\":"+s.watch.Elapsed.TotalSeconds.ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+",\"nodes\":"+s.nodes+",\"harmonic_prunes\":"+s.hprunes+",\"prime_prunes\":"+s.pprunes+",\"memo_hits\":"+s.mhits+",\"quadratic_two_prunes\":"+s.twoPrunes+",\"two_candidates\":"+s.twoCandidates+",\"failed_states\":"+s.failed.Count+"}";}
}
